record.field:
# Polling fallback: query pending J&T orders for status updates
carrier_ids = env['delivery.carrier'].search([('delivery_type', '=', 'jtexpress')])
for carrier in carrier_ids:
    pending_orders = env['carrier.ref.order'].search([
        ('carrier_id', '=', carrier.id),
        ('delivery_status_id.code', 'not in', ['DELIVERED', 'RETURNED', 'CANCELLED']),
    ])
    for order in pending_orders:
        if order.carrier_tracking_ref:
            try:
                from odoo.addons.tangerine_delivery_jtexpress.api.client import Client
                from odoo.addons.tangerine_delivery_jtexpress.settings.constants import settings as jt_settings
                client = Client(carrier)
                result = client.track_order({
                    'customerCode': carrier.jtexpress_customer_code,
                    'password': carrier.jtexpress_password,
                    'txlogisticId': '',
                    'billCodes': order.carrier_tracking_ref,
                })
                # result is data[0]: {"billCode": "...", "details": [...]}
                details = result.get('details') or []
                if details:
                    scan_type_code = details[0].get('scanTypeCode')
                    scan_map = jt_settings.scan_type_code_to_status.value
                    status_code = scan_map.get(int(scan_type_code)) if scan_type_code is not None else None
                    if status_code:
                        status_id = env['delivery.status'].search([
                            ('code', '=', status_code),
                            ('provider_id', '=', carrier.id)
                        ], limit=1)
                        if status_id:
                            order.sudo().write({'delivery_status_id': status_id.id})
                            order.picking_id.sudo().write({'delivery_status_id': status_id.id})
            except Exception as e:
                pass
